    logic [   SEL_WIDTH-1:0] sel_b       [0:NUM_PAIR-1];
    logic [    OP_WIDTH-1:0] ctr_l       [0:NUM_PAIR-1];
    logic [    OP_WIDTH-1:0] ctr_h       [0:NUM_PAIR-1];
    logic [ A_DP8_WIDTH-1:0] a_dp8       [ 0:NUM_DP8-1];
    logic [ B_DP8_WIDTH-1:0] b_dp8       [ 0:NUM_DP8-1];
    logic [             71:0] a_dp8_bpl   [ 0:NUM_DP8-1];
    logic [             39:0] a_sum_dp8   [ 0:NUM_DP8-1];
    logic                    is_signed_a [ 0:NUM_DP8-1];
    logic                    is_signed_b [ 0:NUM_DP8-1];
    logic [   NUM_SHIFT-1:0] sel_shift;
    logic [             2:0] en_level;
    logic [L0_TAP_WIDTH-1:0] l0_sum      [  0:NUM_L0-1];
    logic [L0_TAP_WIDTH-1:0] l0_carry    [  0:NUM_L0-1];
    logic [L1_TAP_WIDTH-1:0] l1_sum      [  0:NUM_L1-1];
    logic [L1_TAP_WIDTH-1:0] l1_carry    [  0:NUM_L1-1];
    logic [L2_TAP_WIDTH-1:0] l2_sum      [  0:NUM_L2-1];
    logic [L2_TAP_WIDTH-1:0] l2_carry    [  0:NUM_L2-1];
    logic [L3_TAP_WIDTH-1:0] l3_sum;
    logic [L3_TAP_WIDTH-1:0] l3_carry;
    logic [ EXP_A_WIDTH-1:0] pe_exp_a;
    logic [ EXP_B_WIDTH-1:0] pe_exp_b;
    logic [EXP_IN_WIDTH-1:0] exp_a_dp8   [ 0:NUM_DP8-1];
    logic [EXP_IN_WIDTH-1:0] exp_b_dp8   [ 0:NUM_DP8-1];
    logic [EXP_IN_WIDTH-1:0] gold_exp_a  [ 0:NUM_DP8-1];
    logic [EXP_IN_WIDTH-1:0] gold_exp_b  [ 0:NUM_DP8-1];
    logic [   EXP_WIDTH-1:0] exp_dp8     [ 0:NUM_DP8-1];
    logic [L0_TAP_WIDTH-1:0] b_l0_sum    [  0:NUM_L0-1];
    logic [L0_TAP_WIDTH-1:0] b_l0_carry  [  0:NUM_L0-1];
    logic [B_L1_TAP_WIDTH-1:0] b_l1_sum    [  0:NUM_L1-1];
    logic [B_L1_TAP_WIDTH-1:0] b_l1_carry  [  0:NUM_L1-1];
    logic [B_L2_TAP_WIDTH-1:0] b_l2_sum    [  0:NUM_L2-1];
    logic [B_L2_TAP_WIDTH-1:0] b_l2_carry  [  0:NUM_L2-1];
    logic [B_L3_TAP_WIDTH-1:0] b_l3_sum;
    logic [B_L3_TAP_WIDTH-1:0] b_l3_carry;
    logic [   EXP_WIDTH-1:0] b_l0_exp    [  0:NUM_L0-1];
    logic [   EXP_WIDTH-1:0] b_l1_exp    [  0:NUM_L1-1];
    logic [   EXP_WIDTH-1:0] b_l2_exp    [  0:NUM_L2-1];
    logic [   EXP_WIDTH-1:0] b_l3_exp;

    logic signed [15:0] A_re [0:MAXM-1][0:MAXK-1];
    logic signed [15:0] A_im [0:MAXM-1][0:MAXK-1];
    logic signed [15:0] B_re [0:MAXK-1][0:MAXN-1];
    logic signed [15:0] B_im [0:MAXK-1][0:MAXN-1];
    longint             X_re [0:MAXO-1];
    longint             X_im [0:MAXO-1];

    int err;
    int npass;

    disp_array_a disp_array_a_i (
        .clk_i    (clk_i),
        .rst_ni   (rst_ni),
        .pe_in_a_i(pe_in_a),
        .sel_a_i  (sel_a),
        .a_dp8_o  (a_dp8)
    );

    disp_array_b disp_array_b_i (
        .clk_i    (clk_i),
        .rst_ni   (rst_ni),
        .pe_in_b_i(pe_in_b),
        .sel_b_i  (sel_b),
        .ctr_l_i  (ctr_l),
        .ctr_h_i  (ctr_h),
        .b_dp8_o  (b_dp8)
    );

    disp_array_a_bpl_b_bfp disp_array_a_bpl_b_bfp_i (
        .clk_i        (clk_i),
        .rst_ni       (rst_ni),
        .pe_in_a_i    (pe_in_a),
        .sel_a_i      (sel_a),
        .is_signed_a_i(is_signed_a),
        .a_dp8_o      (a_dp8_bpl),
        .a_sum_dp8_o  (a_sum_dp8)
    );

    disp_array_exp_a_bfp disp_array_exp_a_bfp_i (
        .clk_i      (clk_i),
        .rst_ni     (rst_ni),
        .pe_exp_a_i (pe_exp_a),
        .sel_a_i    (sel_a),
        .ctr_l_i    (ctr_l),
        .ctr_h_i    (ctr_h),
        .exp_a_dp8_o(exp_a_dp8)
    );

    disp_array_exp_b_bfp disp_array_exp_b_bfp_i (
        .clk_i      (clk_i),
        .rst_ni     (rst_ni),
        .pe_exp_b_i (pe_exp_b),
        .sel_b_i    (sel_b),
        .ctr_l_i    (ctr_l),
        .ctr_h_i    (ctr_h),
        .exp_b_dp8_o(exp_b_dp8)
    );

    pe_array pe_array_i (
        .clk_i        (clk_i),
        .rst_ni       (rst_ni),
        .a_dp8_i      (a_dp8),
        .b_dp8_i      (b_dp8),
        .is_signed_a_i(is_signed_a),
        .is_signed_b_i(is_signed_b),
        .sel_shift_i  (sel_shift),
        .en_level_i   (en_level),
        .l0_sum_o     (l0_sum),
        .l0_carry_o   (l0_carry),
        .l1_sum_o     (l1_sum),
        .l1_carry_o   (l1_carry),
        .l2_sum_o     (l2_sum),
        .l2_carry_o   (l2_carry),
        .l3_sum_o     (l3_sum),
        .l3_carry_o   (l3_carry)
    );

    pe_array_bpl_b_bfp pe_array_bpl_b_bfp_i (
        .clk_i        (clk_i),
        .rst_ni       (rst_ni),
        .a_dp8_i      (a_dp8_bpl),
        .a_sum_dp8_i  (a_sum_dp8),
        .b_dp8_i      (b_dp8),
        .is_signed_b_i(is_signed_b),
        .exp_a_dp8_i  (exp_a_dp8),
        .exp_b_dp8_i  (exp_b_dp8),
        .sel_shift_i  (sel_shift),
        .en_level_i   (en_level),
        .l0_sum_o     (b_l0_sum),
        .l0_carry_o   (b_l0_carry),
        .l0_exp_o     (b_l0_exp),
        .l1_sum_o     (b_l1_sum),
        .l1_carry_o   (b_l1_carry),
        .l1_exp_o     (b_l1_exp),
        .l2_sum_o     (b_l2_sum),
        .l2_carry_o   (b_l2_carry),
        .l2_exp_o     (b_l2_exp),
        .l3_sum_o     (b_l3_sum),
        .l3_carry_o   (b_l3_carry),
        .l3_exp_o     (b_l3_exp)
    );

    initial clk_i = 1'b0;
    always #(CLK_HALF) clk_i = ~clk_i;

    function automatic logic signed [15:0] rand_signed(input int width);
        logic [15:0] r;
        int pk;
        r = 16'($urandom);
        pk = $urandom % 5;
        case (width)
            4:       return (pk == 0) ? -16'sd8     : (pk == 1) ? 16'sd7     : 16'($signed(r[3:0]));
            8:       return (pk == 0) ? -16'sd128   : (pk == 1) ? 16'sd127   : 16'($signed(r[7:0]));
            default: return (pk == 0) ? -16'sd32768 : (pk == 1) ? 16'sd32767 : $signed(r);
        endcase
    endfunction

    function automatic logic signed [15:0] rand_signed_sym(input int width);
        int m;
        m = (1 << (width - 1)) - 1;
        return 16'($signed(($urandom % (2*m + 1)) - m));
    endfunction

    function automatic longint resolve_tap(input int lvl, input int node);
        case (lvl)
            0:       return longint'($signed(l0_sum[node])) + longint'($signed(l0_carry[node]));
            1:       return longint'($signed(l1_sum[node])) + longint'($signed(l1_carry[node]));
            2:       return longint'($signed(l2_sum[node])) + longint'($signed(l2_carry[node]));
            default: return longint'($signed(l3_sum))       + longint'($signed(l3_carry));
        endcase
    endfunction

    function automatic longint resolve_tap_bfp(input int lvl, input int node);
        case (lvl)
            0:       return longint'($signed(b_l0_sum[node])) + longint'($signed(b_l0_carry[node]));
            1:       return longint'($signed(b_l1_sum[node])) + longint'($signed(b_l1_carry[node]));
            2:       return longint'($signed(b_l2_sum[node])) + longint'($signed(b_l2_carry[node]));
            default: return longint'($signed(b_l3_sum))       + longint'($signed(b_l3_carry));
        endcase
    endfunction

    function automatic logic [EXP_WIDTH-1:0] exp_tap_bfp(input int lvl, input int node);
        case (lvl)
            0:       return b_l0_exp[node];
            1:       return b_l1_exp[node];
            2:       return b_l2_exp[node];
            default: return b_l3_exp;
        endcase
    endfunction

    function automatic longint dp8_gold(input int d);
        longint acc;
        longint av;
        longint bv;
        acc = 0;
        for (int ln = 0; ln < 8; ln++) begin
            av = is_signed_a[d] ? longint'($signed(a_dp8[d][ln*8 +: 8])) : longint'(a_dp8[d][ln*8 +: 8]);
            bv = is_signed_b[d] ? longint'($signed(b_dp8[d][ln*4 +: 4])) : longint'(b_dp8[d][ln*4 +: 4]);
            acc = acc + av * bv;
        end
        return acc;
    endfunction

    function automatic bit insub(input int d, input int lvl, input int node);
        int n;
        n = 2*(d/4) + (d%2);
        case (lvl)
            0:       return (n == node);
            1:       return (n/2 == node);
            2:       return (n/4 == node);
            default: return 1'b1;
        endcase
    endfunction

    function automatic logic [EXP_WIDTH-1:0] egold(input int lvl, input int node);
        logic [EXP_WIDTH-1:0] e;
        e = '0;
        for (int d = 0; d < NUM_DP8; d++)
            if (insub(d, lvl, node) && exp_dp8[d] > e) e = exp_dp8[d];
        return e;
    endfunction

    function automatic longint fdiv(input longint x, input int k);
        int kk;
        kk = (k > 63) ? 63 : k;
        return x >>> kk;
    endfunction

    longint gv_l0 [0:NUM_L0-1];
    longint gd_l0 [0:NUM_L0-1];
    longint gv_l1 [0:NUM_L1-1];
    longint gd_l1 [0:NUM_L1-1];
    longint gv_l2 [0:NUM_L2-1];
    longint gd_l2 [0:NUM_L2-1];
    longint gv_l3;
    longint gd_l3;

    task automatic cascade_golden();
        int s0;
        int s1;
        int s2;
        int cx0;
        int cx1;
        int e;
        int dhi;
        int dlo;
        longint vhi;
        longint dh;
        longint dl;
        s0 = sel_shift[0] ? 8 : 0;
        s1 = sel_shift[1] ? 4 : 0;
        s2 = sel_shift[2] ? 8 : 0;
        for (int n = 0; n < NUM_L0; n++) begin
            cx0 = 4*(n/2) + (n%2);
            cx1 = cx0 + 2;
            e   = int'(egold(0, n));
            dhi = e - int'(exp_dp8[cx0]);
            dlo = e - int'(exp_dp8[cx1]);
            gv_l0[n] = fdiv(dp8_gold(cx0) <<< s0, dhi) + fdiv(dp8_gold(cx1), dlo);
            gd_l0[n] = longint'((dhi > 0) ? 1 : 0) + longint'((dlo > 0) ? 1 : 0);
        end
        for (int j = 0; j < NUM_L1; j++) begin
            gv_l1[j] = (gv_l0[2*j] <<< s1) + gv_l0[2*j+1];
            gd_l1[j] = (gd_l0[2*j] <<< s1) + gd_l0[2*j+1];
        end
        for (int k = 0; k < NUM_L2; k++) begin
            e   = int'(egold(2, k));
            dhi = e - int'(egold(1, 2*k));
            dlo = e - int'(egold(1, 2*k+1));
            vhi = gv_l1[2*k] <<< s2;
            dh  = gd_l1[2*k] <<< s2;
            dl  = gd_l1[2*k+1];
            gv_l2[k] = fdiv(vhi, dhi) + fdiv(gv_l1[2*k+1], dlo);
            gd_l2[k] = ((dhi > 0) ? (fdiv(dh, dhi) + 1) : dh)
                     + ((dlo > 0) ? (fdiv(dl, dlo) + 1) : dl);
        end
        begin
            e   = int'(egold(3, 0));
            dhi = e - int'(egold(2, 0));
            dlo = e - int'(egold(2, 1));
            gv_l3 = fdiv(gv_l2[0], dhi) + fdiv(gv_l2[1], dlo);
            gd_l3 = ((dhi > 0) ? (fdiv(gd_l2[0], dhi) + 1) : gd_l2[0])
                  + ((dlo > 0) ? (fdiv(gd_l2[1], dlo) + 1) : gd_l2[1]);
        end
    endtask

    function automatic int ebias(input int base);
        int d;
        case ($urandom_range(0, 7))
            0:       d = 0;
            1:       d = 1;
            2:       d = 7;
            3:       d = 8;
            4:       d = 27;
            5:       d = 28;
            6:       d = 56;
            default: d = int'($urandom_range(0, 63));
        endcase
        if ($urandom_range(0, 1) == 1) d = -d;
        d = base + d;
        if (d < 0) d = 0;
        if (d > 63) d = 63;
        return d;
    endfunction

    task automatic set_exps(input int mi, input bit equal);
        int base;
        int ga [0:3];
        int gb [0:7];
        logic [5:0] ea [0:3];
        logic [5:0] eb [0:7];
        base = int'($urandom_range(0, 63));
        for (int g = 0; g < 4; g++) ga[g] = equal ? base : ebias(base);
        for (int g = 0; g < 8; g++) gb[g] = equal ? base : ebias(base);
        for (int blk = 0; blk < 4; blk++) ea[blk] = 6'(ga[EGRP_A[mi][blk]]);
        for (int h = 0; h < 8; h++)      eb[h]   = 6'(gb[EGRP_B[mi][h]]);
        for (int blk = 0; blk < NUM_BLK; blk++) begin
            pe_exp_a[blk*EXP_IN_WIDTH +: EXP_IN_WIDTH]           = ea[blk];
            pe_exp_b[blk*CHK_WIDTH+EXP_IN_WIDTH +: EXP_IN_WIDTH] = eb[2*blk];
            pe_exp_b[blk*CHK_WIDTH +: EXP_IN_WIDTH]              = eb[2*blk+1];
        end
        for (int p = 0; p < NUM_PAIR; p++) begin
            gold_exp_a[2*p]   = (CTR_H[mi][p] == 2'd1) ? '0 : ea[SEL_A[mi][p]];
            gold_exp_b[2*p]   = (CTR_H[mi][p] == 2'd1) ? '0 : eb[int'(SEL_B[mi][p])*2];
            gold_exp_a[2*p+1] = (CTR_L[mi][p] == 2'd1) ? '0 : ea[SEL_A[mi][p]];
            gold_exp_b[2*p+1] = (CTR_L[mi][p] == 2'd1) ? '0 : eb[int'(SEL_B[mi][p])*2+1];
        end
        for (int i = 0; i < NUM_DP8; i++)
            exp_dp8[i] = EXP_WIDTH'(gold_exp_a[i]) + EXP_WIDTH'(gold_exp_b[i]);
    endtask


    task automatic check_equal(input int mi);
        for (int n = 0; n < NUM_L0; n++)
            if (L0_TAP_WIDTH'(b_l0_sum[n] + b_l0_carry[n]) !== L0_TAP_WIDTH'(l0_sum[n] + l0_carry[n])) begin
                err = err + 1;
                $display("mode %0d equal-exp L0[%0d] value mismatch: bpl %0h base %0h", MODE_NUM[mi], n,
                         L0_TAP_WIDTH'(b_l0_sum[n] + b_l0_carry[n]), L0_TAP_WIDTH'(l0_sum[n] + l0_carry[n]));
            end
        for (int j = 0; j < NUM_L1; j++)
            if (L1_TAP_WIDTH'(b_l1_sum[j] + b_l1_carry[j]) !== L1_TAP_WIDTH'(l1_sum[j] + l1_carry[j])) begin
                err = err + 1;
                $display("mode %0d equal-exp L1[%0d] value mismatch: bpl %0h base %0h", MODE_NUM[mi], j,
                         L1_TAP_WIDTH'(b_l1_sum[j] + b_l1_carry[j]), L1_TAP_WIDTH'(l1_sum[j] + l1_carry[j]));
            end
        for (int k = 0; k < NUM_L2; k++)
            if (L2_TAP_WIDTH'(b_l2_sum[k] + b_l2_carry[k]) !== L2_TAP_WIDTH'(l2_sum[k] + l2_carry[k])) begin
                err = err + 1;
                $display("mode %0d equal-exp L2[%0d] value mismatch: bpl %0h base %0h", MODE_NUM[mi], k,
                         L2_TAP_WIDTH'(b_l2_sum[k] + b_l2_carry[k]), L2_TAP_WIDTH'(l2_sum[k] + l2_carry[k]));
            end
        if (L3_TAP_WIDTH'(b_l3_sum + b_l3_carry) !== L3_TAP_WIDTH'(l3_sum + l3_carry)) begin
            err = err + 1;
            $display("mode %0d equal-exp L3 value mismatch: bpl %0h base %0h", MODE_NUM[mi],
                     L3_TAP_WIDTH'(b_l3_sum + b_l3_carry), L3_TAP_WIDTH'(l3_sum + l3_carry));
        end
    endtask

    task automatic check_exps(input int mi);
        for (int n = 0; n < NUM_L0; n++)
            if (b_l0_exp[n] !== egold(0, n)) begin
                err = err + 1;
                $display("mode %0d L0[%0d] exp: dut %0d gold %0d", MODE_NUM[mi], n, b_l0_exp[n], egold(0, n));
            end
        for (int j = 0; j < NUM_L1; j++)
            if (b_l1_exp[j] !== egold(1, j)) begin
                err = err + 1;
                $display("mode %0d L1[%0d] exp: dut %0d gold %0d", MODE_NUM[mi], j, b_l1_exp[j], egold(1, j));
            end
        for (int k = 0; k < NUM_L2; k++)
            if (b_l2_exp[k] !== egold(2, k)) begin
                err = err + 1;
                $display("mode %0d L2[%0d] exp: dut %0d gold %0d", MODE_NUM[mi], k, b_l2_exp[k], egold(2, k));
            end
        if (b_l3_exp !== egold(3, 0)) begin
            err = err + 1;
            $display("mode %0d L3 exp: dut %0d gold %0d", MODE_NUM[mi], b_l3_exp, egold(3, 0));
        end
    endtask

    task automatic check_disp_exps(input int mi);
        for (int i = 0; i < NUM_DP8; i++)
            if (exp_a_dp8[i] !== gold_exp_a[i] || exp_b_dp8[i] !== gold_exp_b[i]) begin
                err = err + 1;
                $display("mode %0d disp exp dp8=%0d: a dut %0d gold %0d, b dut %0d gold %0d",
                         MODE_NUM[mi], i, exp_a_dp8[i], gold_exp_a[i], exp_b_dp8[i], gold_exp_b[i]);
            end
    endtask

    task automatic check_bounds(input int mi);
        longint r;
        longint ideal;
        longint allow;
        int lvl;
        int nn;
        lvl = TAP_LEVEL[mi];
        nn  = (lvl == 0) ? NUM_L0 : (lvl == 1) ? NUM_L1 : (lvl == 2) ? NUM_L2 : 1;
        cascade_golden();
        for (int node = 0; node < nn; node++) begin
            r = resolve_tap_bfp(lvl, node);
            case (lvl)
                0: begin ideal = gv_l0[node]; allow = gd_l0[node]; end
                1: begin ideal = gv_l1[node]; allow = gd_l1[node]; end
                2: begin ideal = gv_l2[node]; allow = gd_l2[node]; end
                default: begin ideal = gv_l3; allow = gd_l3; end
            endcase
            if (r > ideal || r < ideal - allow - 1) begin
                err = err + 1;
                $display("mode %0d L%0d[%0d] bound: dut %0d ideal %0d allow %0d (exp %0d)",
                         MODE_NUM[mi], lvl, node, r, ideal, allow, exp_tap_bfp(lvl, node));
            end
        end
    endtask

    task automatic set_controls(input int mi);
        for (int p = 0; p < NUM_PAIR; p++) begin
            sel_a[p] = SEL_A[mi][p];
            sel_b[p] = SEL_B[mi][p];
            ctr_l[p] = CTR_L[mi][p];
            ctr_h[p] = CTR_H[mi][p];
        end
        for (int i = 0; i < NUM_DP8; i++) begin
            is_signed_a[i] = IS_SIGNED_A[mi][i];
            is_signed_b[i] = IS_SIGNED_B[mi][i];
            if ((i % 2 == 0) ? (CTR_H[mi][i/2] == 2'd1) : (CTR_L[mi][i/2] == 2'd1)) is_signed_b[i] = 1'b0;
        end
        sel_shift = SEL_SHIFT[mi];
        en_level  = {TAP_LEVEL[mi] >= 3, TAP_LEVEL[mi] >= 2, TAP_LEVEL[mi] >= 1};
    endtask

    task automatic rand_matrices(input int mi);
        int M, K, N, PA, PB, cplx;
        M = MM_DIMS[mi][0]; K = MM_DIMS[mi][1]; N = MM_DIMS[mi][2];
        PA = MM_DIMS[mi][3]; PB = MM_DIMS[mi][4]; cplx = MM_DIMS[mi][5];
        for (int m = 0; m < M; m++)
            for (int k = 0; k < K; k++) begin
                A_re[m][k] = rand_signed(PA);
                A_im[m][k] = (cplx != 0) ? rand_signed(PA) : 16'sd0;
            end
        for (int k = 0; k < K; k++)
            for (int n = 0; n < N; n++) begin
                B_re[k][n] = rand_signed(PB);
                B_im[k][n] = (cplx != 0) ? rand_signed_sym(PB) : 16'sd0;
            end
    endtask

    task automatic golden(input int mi);
        int K, NOUT, m, n;
        longint re, im;
        K = MM_DIMS[mi][1]; NOUT = MM_DIMS[mi][6];
        for (int o = 0; o < NOUT; o++) begin
            m = MM_OUT[mi][o][0]; n = MM_OUT[mi][o][1];
            re = 0; im = 0;
            for (int k = 0; k < K; k++) begin
                re = re + longint'(A_re[m][k]) * longint'(B_re[k][n])
                        - longint'(A_im[m][k]) * longint'(B_im[k][n]);
                im = im + longint'(A_re[m][k]) * longint'(B_im[k][n])
                        + longint'(A_im[m][k]) * longint'(B_re[k][n]);
            end
            X_re[o] = re;
            X_im[o] = im;
        end
    endtask

    task automatic pack(input int mi);
        int M, K, N, PA, cplx, pos;
        pe_in_a = '0;
        pe_in_b = '0;
        M = MM_DIMS[mi][0]; K = MM_DIMS[mi][1]; N = MM_DIMS[mi][2];
        PA = MM_DIMS[mi][3]; cplx = MM_DIMS[mi][5];
        for (int m = 0; m < M; m++)
            for (int k = 0; k < K; k++) begin
                pos = MM_RE_A[mi][m][k] & 255;
                if (pos != 255) pe_in_a[pos*8 +: 8] = A_re[m][k][7:0];
                if (PA == 16) begin
                    pos = (MM_RE_A[mi][m][k] >> 8) & 255;
                    if (pos != 255) pe_in_a[pos*8 +: 8] = A_re[m][k][15:8];
                end
                if (cplx != 0) begin
                    pos = MM_IM_A[mi][m][k] & 255;
                    if (pos != 255) pe_in_a[pos*8 +: 8] = A_im[m][k][7:0];
                    if (PA == 16) begin
                        pos = (MM_IM_A[mi][m][k] >> 8) & 255;
                        if (pos != 255) pe_in_a[pos*8 +: 8] = A_im[m][k][15:8];
                    end
                end
            end
        if (MODE_NUM[mi] == 12)
            pack_b_c16c16();
        else
            for (int k = 0; k < K; k++)
                for (int n = 0; n < N; n++)
                    for (int p = 0; p < 4; p++) begin
                        pos = (MM_RE_B[mi][k][n] >> (8*p)) & 255;
                        if (pos != 255) pe_in_b[pos*4 +: 4] = B_re[k][n][p*4 +: 4];
                        if (cplx != 0) begin
                            pos = (MM_IM_B[mi][k][n] >> (8*p)) & 255;
                            if (pos != 255) pe_in_b[pos*4 +: 4] = B_im[k][n][p*4 +: 4];
                        end
                    end
    endtask

    task automatic put_b16(input logic [15:0] v, input int blk_hi, input int blk_lo, input int lane);
        pe_in_b[(blk_hi*16 + 8 + lane)*4 +: 4] = v[15:12];
        pe_in_b[(blk_hi*16     + lane)*4 +: 4] = v[11:8];
        pe_in_b[(blk_lo*16 + 8 + lane)*4 +: 4] = v[7:4];
        pe_in_b[(blk_lo*16     + lane)*4 +: 4] = v[3:0];
    endtask

    task automatic pack_b_c16c16;
        for (int k = 0; k < 4; k++) begin
            put_b16( B_re[k][0], 0, 1, k);
            put_b16(-B_im[k][0], 0, 1, 4 + k);
            put_b16( B_im[k][0], 2, 3, k);
            put_b16( B_re[k][0], 2, 3, 4 + k);
        end
    endtask

    task automatic compare(input int mi);
        int NOUT, lvl, rn, in;
        longint r;
        NOUT = MM_DIMS[mi][6]; lvl = TAP_LEVEL[mi];
        for (int o = 0; o < NOUT; o++) begin
            rn = MM_OUT[mi][o][2];
            in = MM_OUT[mi][o][3];
            r = resolve_tap(lvl, rn);
            if (r !== X_re[o]) begin
                err = err + 1;
                $display("mode %0d output %0d Re: golden=%0d dut=%0d", MODE_NUM[mi], o, X_re[o], r);
            end
            if (in >= 0) begin
                r = resolve_tap(lvl, in);
                if (r !== X_im[o]) begin
                    err = err + 1;
                    $display("mode %0d output %0d Im: golden=%0d dut=%0d", MODE_NUM[mi], o, X_im[o], r);
                end
            end
        end
    endtask

    initial begin
        int err0;
        $display("\nStarting pe_array_bpl_b_bfp (with disp_array) verification (%0d modes x %0d random)...\n", NUM_MODE, NUM_RAND);
`ifdef VCD
        $dumpfile("activity.vcd");
        $dumpvars(0, tb_pe_array_bpl_b_bfp);
`endif

        rst_ni  = 1'b0;
        pe_in_a = '0;
        pe_in_b = '0;
        for (int p = 0; p < NUM_PAIR; p++) begin
            sel_a[p] = '0; sel_b[p] = '0; ctr_l[p] = '0; ctr_h[p] = '0;
        end
        for (int i = 0; i < NUM_DP8; i++) begin
            is_signed_a[i] = 1'b0; is_signed_b[i] = 1'b0;
        end
        sel_shift = '0; en_level = '1;
        pe_exp_a = '0;
        pe_exp_b = '0;
        for (int i = 0; i < NUM_DP8; i++) begin
            gold_exp_a[i] = '0; gold_exp_b[i] = '0; exp_dp8[i] = '0;
        end
        err = 0; npass = 0;
        repeat (3) @(posedge clk_i);
        rst_ni = 1'b1;

        for (int mi = 0; mi < NUM_MODE; mi++) begin
            set_controls(mi);
            err0 = err;
            for (int t = 0; t < NUM_RAND; t++) begin
                rand_matrices(mi);
                golden(mi);
                pack(mi);
                set_exps(mi, 1'b1);
                @(posedge clk_i);
                @(posedge clk_i);
                #(T_SETTLE);
                compare(mi);
                check_equal(mi);
                check_disp_exps(mi);
                check_exps(mi);
                set_exps(mi, 1'b0);
                @(posedge clk_i);
                @(posedge clk_i);
                #(T_SETTLE);
                check_disp_exps(mi);
                check_exps(mi);
                check_bounds(mi);
            end
            if (err == err0) begin
                npass = npass + 1;
                $display("  mode %0d: PASS", MODE_NUM[mi]);
            end else
                $display("  mode %0d: FAIL (%0d mismatches)", MODE_NUM[mi], err - err0);
        end

`ifdef VCD
        $dumpoff;
`endif
        $display("\npe_array_bpl_b_bfp verification: %0d/%0d modes passed (%0d total mismatches)\n",
                 npass, NUM_MODE, err);
        $finish;
    end

endmodule
